ALTER TABLE public.transactions ADD COLUMN IF NOT EXISTS discount_amount numeric NOT NULL DEFAULT 0;
CREATE TABLE public.serenity_discount_audits (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 transaction_id bigint NOT NULL UNIQUE REFERENCES public.transactions(id) ON DELETE CASCADE,
 membership_id text NOT NULL,
 eligible_amount numeric NOT NULL CHECK (eligible_amount > 0),
 discount_rate numeric NOT NULL DEFAULT 0.05 CHECK (discount_rate = 0.05),
 discount_amount numeric NOT NULL CHECK (discount_amount = round(eligible_amount * 0.05, 2)),
 discount_type text NOT NULL,
 original_total numeric NOT NULL,
 final_total numeric NOT NULL,
 transaction_date timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.serenity_discount_audits TO anon, authenticated;
GRANT ALL ON public.serenity_discount_audits TO service_role;
ALTER TABLE public.serenity_discount_audits ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff can read discount audits" ON public.serenity_discount_audits FOR SELECT TO anon, authenticated USING (true);
CREATE FUNCTION public.apply_booking_loyalty(p_id bigint, p_token text, p_package_type text, p_eligible numeric, p_expected_total numeric) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE t public.transactions; m public.serenity_members; s public.settings; d numeric; ceiling numeric; days numeric; room_charges numeric;
BEGIN
 SELECT * INTO t FROM public.transactions WHERE id = p_id FOR UPDATE;
 IF NOT FOUND OR t.module <> 'Booking' OR t.status = 'Cancelled' THEN RAISE EXCEPTION 'Active booking required'; END IF;
 SELECT * INTO m FROM public.serenity_members WHERE qr_token = p_token FOR SHARE;
 IF NOT FOUND OR m.status <> 'Active' OR m.issue_date > (now() AT TIME ZONE 'Asia/Manila')::date OR m.expiry_date < (now() AT TIME ZONE 'Asia/Manila')::date THEN RAISE EXCEPTION 'Membership is not active or has expired'; END IF;
 IF EXISTS (SELECT 1 FROM public.serenity_discount_audits WHERE transaction_id=p_id) OR t.discount_amount > 0 THEN RAISE EXCEPTION 'A discount already exists; discounts cannot be combined'; END IF;
 IF t.amount_paid <> p_expected_total THEN RAISE EXCEPTION 'Booking changed. Reopen the discount preview'; END IF;
 SELECT * INTO s FROM public.settings WHERE id='default';
 days := GREATEST(1, ceil(EXTRACT(epoch FROM (NULLIF(t.check_out,'')::timestamptz - NULLIF(t.check_in,'')::timestamptz))/86400));
 room_charges := (CASE WHEN t.room_type LIKE '%Kubo Room%' THEN COALESCE(s.kubo_room_rate,1000) ELSE 0 END + CASE WHEN t.room_type LIKE '%Barkada Room%' THEN COALESCE(s.barkada_room_rate,1500) ELSE 0 END) * days;
 ceiling := CASE p_package_type
 WHEN 'Room accommodation' THEN room_charges
 WHEN 'Function hall' THEN COALESCE(t.function_hall_fee,0) + COALESCE(t.function_hall_total,0)
 WHEN 'Exclusive resort' THEN CASE WHEN t.booking_type='Exclusive' THEN COALESCE(s.exclusive_fee,5000) ELSE 0 END
 ELSE 0 END;
 ceiling := LEAST(ceiling, t.amount_paid - COALESCE(t.maintenance_fee,0) - COALESCE(t.drinks_corkage_fee,0) - COALESCE(t.liquor_corkage_fee,0) - COALESCE(t.extension_fee,0) - COALESCE(t.number_of_tables,0)*COALESCE(s.table_rent_rate,200));
 IF p_eligible IS NULL OR p_eligible <= 0 OR p_eligible > ceiling THEN RAISE EXCEPTION 'Only confirmed package charges are eligible; exclude entrance and add-ons'; END IF;
 d := round(p_eligible * 0.05,2);
 IF COALESCE(t.deposit_amount,0) > t.amount_paid-d THEN RAISE EXCEPTION 'Discount would exceed unpaid charges. Previously received payments cannot be changed'; END IF;
 UPDATE public.transactions SET amount_paid=t.amount_paid-d, balance=GREATEST(0,t.amount_paid-d-COALESCE(t.deposit_amount,0)), discount_amount=d,
 payment_status=CASE WHEN t.amount_paid-d=COALESCE(t.deposit_amount,0) THEN 'Fully Paid' WHEN COALESCE(t.deposit_amount,0)>0 THEN 'Partially Paid' ELSE 'Unpaid' END,
 date_settled=CASE WHEN t.amount_paid-d=COALESCE(t.deposit_amount,0) THEN COALESCE(t.date_settled,(now() AT TIME ZONE 'Asia/Manila')::date::text) ELSE t.date_settled END WHERE id=p_id;
 INSERT INTO public.serenity_discount_audits(transaction_id,membership_id,eligible_amount,discount_amount,discount_type,original_total,final_total,transaction_date)
 VALUES(p_id,m.member_id,p_eligible,d,'Package: '||p_package_type,t.amount_paid,t.amount_paid-d,t.date_time);
END $$;
GRANT EXECUTE ON FUNCTION public.apply_booking_loyalty(bigint,text,text,numeric,numeric) TO anon, authenticated;
CREATE FUNCTION public.record_loyalty_entrance(p_transaction jsonb, p_token text, p_excluded_adults integer, p_other_discount numeric) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE t public.transactions; m public.serenity_members; s public.settings; adult_rate numeric; k8_rate numeric; k5_rate numeric; eligible numeric; d numeric; original numeric; new_id bigint;
BEGIN
 t := jsonb_populate_record(NULL::public.transactions,p_transaction);
 SELECT * INTO m FROM public.serenity_members WHERE qr_token=p_token FOR SHARE;
 IF NOT FOUND OR m.status <> 'Active' OR m.issue_date > (now() AT TIME ZONE 'Asia/Manila')::date OR m.expiry_date < (now() AT TIME ZONE 'Asia/Manila')::date THEN RAISE EXCEPTION 'Membership is not active or has expired'; END IF;
 IF t.module <> 'Entrance' OR t.payment_method NOT IN ('Cash','GCash') OR COALESCE(p_other_discount,0) <> 0 OR COALESCE(t.discount_amount,0) <> 0 THEN RAISE EXCEPTION 'Personal discount is walk-in only and cannot be combined'; END IF;
 IF p_excluded_adults IS NULL OR p_excluded_adults < 0 OR p_excluded_adults > t.adults OR t.adults-p_excluded_adults < 5 OR t.children < 0 OR t.kids_8_above < 0 OR t.kids_5_7 < 0 OR t.kids_4_below < 0 THEN RAISE EXCEPTION 'At least five full-fee paying adults required'; END IF;
 SELECT * INTO s FROM public.settings WHERE id='default';
 IF t.tour_type='Day Tour' THEN adult_rate:=COALESCE(s.adult_rate_day,100); k8_rate:=COALESCE(s.kids_8_above_rate_day,50); k5_rate:=COALESCE(s.kids_5_7_rate_day,30);
 ELSIF t.tour_type='Overnight' THEN adult_rate:=COALESCE(s.adult_rate_night,150); k8_rate:=COALESCE(s.kids_8_above_rate_night,75); k5_rate:=COALESCE(s.kids_5_7_rate_night,50);
 ELSE RAISE EXCEPTION 'Invalid tour type'; END IF;
 eligible:=round((t.adults-p_excluded_adults)*adult_rate+t.kids_8_above*k8_rate+t.kids_5_7*k5_rate,2);
 d:=round(eligible*0.05,2); original:=t.amount_paid+d;
 IF adult_rate <= 0 OR t.amount_paid < 0 OR original < eligible+COALESCE(t.function_hall_total,0)+COALESCE(t.maintenance_fee,0)+COALESCE(t.drinks_corkage_fee,0)+COALESCE(t.liquor_corkage_fee,0) THEN RAISE EXCEPTION 'Entrance amounts changed. Review the total'; END IF;
 IF EXISTS(SELECT 1 FROM public.transactions WHERE transaction_no=t.transaction_no) THEN RAISE EXCEPTION 'Transaction already saved'; END IF;
 INSERT INTO public.transactions(transaction_no,date_time,module,customer_name,adults,children,total_headcount,amount_paid,payment_method,tour_type,entry_time,kids_8_above,kids_5_7,kids_4_below,with_function_hall,function_hall_days,function_hall_rate,function_hall_total,maintenance_fee,drinks_corkage_fee,liquor_corkage_fee,deposit_amount,balance,payment_status,discount_amount)
 VALUES(t.transaction_no,t.date_time,'Entrance',t.customer_name,t.adults,t.children,t.total_headcount,t.amount_paid,t.payment_method,t.tour_type,t.entry_time,t.kids_8_above,t.kids_5_7,t.kids_4_below,t.with_function_hall,t.function_hall_days,t.function_hall_rate,t.function_hall_total,t.maintenance_fee,t.drinks_corkage_fee,t.liquor_corkage_fee,t.amount_paid,0,'Fully Paid',d) RETURNING id INTO new_id;
 INSERT INTO public.serenity_discount_audits(transaction_id,membership_id,eligible_amount,discount_amount,discount_type,original_total,final_total,transaction_date)
 VALUES(new_id,m.member_id,eligible,d,'Entrance',original,t.amount_paid,t.date_time);
 RETURN new_id;
END $$;
GRANT EXECUTE ON FUNCTION public.record_loyalty_entrance(jsonb,text,integer,numeric) TO anon, authenticated;
CREATE FUNCTION public.guard_loyalty_total() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.serenity_discount_audits WHERE transaction_id=OLD.id) AND (NEW.amount_paid IS DISTINCT FROM OLD.amount_paid OR NEW.discount_amount IS DISTINCT FROM OLD.discount_amount OR NEW.room_type IS DISTINCT FROM OLD.room_type OR NEW.function_hall_total IS DISTINCT FROM OLD.function_hall_total OR NEW.function_hall_fee IS DISTINCT FROM OLD.function_hall_fee) THEN RAISE EXCEPTION 'Discounted charges are locked to preserve the audit; payment and schedule updates are still allowed'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_loyalty_total BEFORE UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.guard_loyalty_total();